use ieee.std_logic_1164.all;
use ieee.numeric_std.all;

entity deriv_buffer is
  generic(
    NSAMPLES : natural := 16;
    buf_size  : natural := 5
  );
  port(
    clk          : in std_logic;
    rst          : in std_logic;
    we           : in std_logic;  -- Write enable
    addr         : in natural;    -- Address to write
    deriv_s      : in t_deriv_array(NSAMPLES - 1 downto 0);
    deriv_buf    : out t_deriv_array(buf_size * NSAMPLES - 1 downto 0)
  );
end deriv_buffer;

architecture Behavioral of deriv_buffer is

  type mem_array is array(0 to (buf_size * NSAMPLES - 1)) of t_deriv_type; -- Use the type you defined for the data
  signal deriv_buf_s : mem_array;
  attribute ram_style : string;
  attribute ram_style of deriv_buf_s : signal is "block";

begin

  process(clk, rst)
  begin
    if rst = '1' then
      deriv_buf_s <= (others => (others => '0'));
    elsif rising_edge(clk) then
      if we = '1' then
        deriv_buf_s(addr * NSAMPLES + (0 to NSAMPLES - 1)) <= deriv_s;
      end if;
    end if;
  end process;

  -- Output assignments
  derive_buf <= (others => (others => '0')); -- Default to zero or assign as required.
  deriv_buf <= deriv_buf_s;

end Behavioral;
```

### Explanation of Changes:

- **Memory Definition**: A memory array `deriv_buf_s` is defined using a composite type to store multiple samples. This avoids the complexity of shifting old values manually.

- **Write Enable**: A `we` (write enable) port is added to control when data should be written to the block RAM.

